/** Commands that deploy to and operate Cursor-managed hosting. */
import { cmdCancelRuns, cmdDelete, cmdDeploy, cmdDeploymentStatus, cmdDeployments, cmdEventRepos, cmdKill, cmdRollback, cmdRotateToken, cmdSecretsList, cmdSecretsSet, cmdSecretsUnset, cmdStart, cmdStop, cmdUnlockDeploys, cmdUpgrade, } from "../../cli-deploy.js";
import { cmdImagesList, cmdImagesPush, cmdImagesRm } from "../../cli-images.js";
import { openBrowser } from "../../open-browser.js";
import { prodDeploymentUrl } from "../../resolve-prod-target.js";
import { defineCommand, positionalIndex } from "../command.js";
import { CliUsageError } from "../errors.js";
import { apiKeyFlag, dryRunFlag, fieldsFlag, jsonFlag, limitFlags, noWaitFlag, teamFlag, yesFlag, } from "../flags.js";
import { listValues } from "../output.js";
/** Flags every hosted command reads: account, team, and output. */
const hostedFlags = { ...teamFlag, ...apiKeyFlag, ...jsonFlag };
/** A hosted command that changes state: --dry-run stops at its first change. */
const writeFlags = { ...dryRunFlag, ...hostedFlags };
/** A hosted command that cannot be undone: it also asks, unless --yes. */
const destructiveFlags = { ...dryRunFlag, ...yesFlag, ...hostedFlags };
const slugArg = {
    name: "slug",
    description: "Deployment slug.",
    required: true,
    kind: "slug",
};
function deployOptions(values) {
    return {
        team: values.team,
        json: values.json === true,
        ...listValues(values),
        noWait: values["no-wait"] === true,
        cancelRuns: values["cancel-runs"] === true,
        apiKey: values["api-key"],
        fromArgv: values["from-argv"] === true ? true : undefined,
    };
}
export const deployCommand = defineCommand({
    name: "deploy",
    group: "deploy",
    summary: "Deploy the agent to Cursor-managed hosting and wait until it runs.",
    description: `
Builds from a pushed git ref. Inside an agent git checkout, --repo, --ref, and
--path are inferred when omitted (flags always win). When --dir is a parent of
several agents, pick one interactively, or pass --slug or --all. The first
deploy of a slug prints the alias token once. Save it.`,
    flags: {
        dir: {
            type: "string",
            value: "<path>",
            kind: "path",
            description: "Project root, or a folder of agent projects. Defaults to the current folder.",
        },
        slug: {
            type: "string",
            value: "<slug>",
            kind: "slug",
            description: "Deploy only this child agent.",
        },
        all: {
            type: "boolean",
            description: "Deploy every child agent under --dir (skips the picker).",
        },
        repo: {
            type: "string",
            value: "<url>",
            description: "https git repo to build from. Defaults to the origin remote.",
        },
        ref: {
            type: "string",
            value: "<ref>",
            description: "Git ref to build. Defaults to the current branch.",
        },
        path: {
            type: "string",
            value: "<agentPath>",
            kind: "path",
            description: "Agent folder relative to the repo root. Defaults to --dir.",
        },
        "cursor-events-repo": {
            type: "string",
            multiple: true,
            value: "<repo>",
            description: "Repository the agent watches: owner/name, gitlab.com/<group>/<project>, or bitbucket.org/<workspace>/<repo>.",
        },
        "multi-tenant": {
            type: "boolean",
            hidden: true,
            description: "Add a release to an existing Cursor-managed product.",
        },
        ...noWaitFlag,
        ...writeFlags,
    },
    effect: "write",
    examples: ["agent-sdk deploy", "agent-sdk deploy --dir ./agents --slug triage --no-wait --json"],
    async run({ values }) {
        return cmdDeploy({
            ...deployOptions(values),
            dir: values.dir,
            slug: values.slug,
            all: values.all === true,
            repo: values.repo,
            ref: values.ref,
            path: values.path,
            cursorEventsRepos: values["cursor-events-repo"],
            multiTenant: values["multi-tenant"] === true,
        });
    },
});
export const deploymentListCommand = defineCommand({
    name: "deployment list",
    aliases: ["deployments"],
    group: "deploy",
    parentSummary: "Show and operate hosted deployments.",
    summary: "List the team's deployments.",
    description: "--json prints { items, nextPageToken }. Pass the token as --page-token for the next page.",
    flags: { ...limitFlags, ...fieldsFlag, ...hostedFlags },
    examples: ["agent-sdk deployment list --json --fields slug,status --limit 50"],
    effect: "read",
    async run({ values }) {
        return cmdDeployments(deployOptions(values));
    },
});
export const deploymentGetCommand = defineCommand({
    name: "deployment get",
    // The old one-word form ran with a slug; bare `deployment` now lists subcommands.
    aliases: [{ name: "deployment", when: (rest, flags) => positionalIndex(rest, flags) !== -1 }],
    group: "deploy",
    summary: "Show one deployment: status, release, and last error.",
    description: "A deployment still on architecture v1 shows its status and the steps to migrate it.",
    args: [slugArg],
    flags: {
        web: {
            type: "boolean",
            description: "Open the deployment's page in the Cursor dashboard. Print its URL.",
        },
        ...fieldsFlag,
        ...hostedFlags,
    },
    effect: "read",
    async run({ values, positionals, io }) {
        if (values.web === true) {
            const url = prodDeploymentUrl(positionals[0] ?? "");
            await io.stdout(values.json === true ? `${JSON.stringify({ url }, null, 2)}\n` : `${url}\n`);
            openBrowser(url);
            return 0;
        }
        return cmdDeploymentStatus(positionals[0], deployOptions(values));
    },
});
export const deploymentStopCommand = defineCommand({
    name: "deployment stop",
    aliases: ["stop"],
    group: "deploy",
    summary: "Stop every install of a deployment and wait until it reports stopped.",
    description: "Does not lock deploys. Also stops a deployment still on architecture v1.",
    args: [slugArg],
    flags: {
        "cancel-runs": {
            type: "boolean",
            description: "Also cancel this install's active session runs and reminder clocks (not every tenant).",
        },
        ...noWaitFlag,
        ...writeFlags,
    },
    effect: "write",
    async run({ values, positionals }) {
        return cmdStop(positionals[0], deployOptions(values));
    },
});
