export const secretSetCommand = defineCommand({
    name: "secret set",
    aliases: ["secrets set"],
    group: "deploy",
    parentSummary: "Manage deployment secrets (names only; values never print).",
    summary: "Set deployment secrets from a hidden prompt or piped stdin.",
    description: "Pass names only. NAME=VALUE needs --from-argv, because argv leaks into shell history and agent-captured terminals.",
    args: [slugArg, { name: "NAME", description: "Secret name.", variadic: true }],
    flags: {
        "from-argv": { type: "boolean", description: "Accept NAME=VALUE on argv." },
        ...writeFlags,
    },
    effect: "write",
    examples: ['printf %s "$TOKEN" | agent-sdk secret set my-agent GITHUB_TOKEN'],
    async run({ values, positionals }) {
        return cmdSecretsSet(positionals[0], positionals.slice(1), deployOptions(values));
    },
});
